const fs = require('fs');
const GW = 'http://127.0.0.1:8787';
const MOD = 'http://127.0.0.1:5780/webhook/moderation-draft';
const ENV0 = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
// host-side chart renderer (tools/render_viz.py --serve); the n8n
// container has no python/matplotlib. Rootless docker network_mode:host
// is a shared slirp4netns netns - the real host is reached via its
// gateway 10.0.2.2, NOT via loopback (loopback is the netns itself).
const VIZ = ENV0('VIZ_RENDERER_URL') || 'http://10.0.2.2:8791/render';
fs.mkdirSync('/home/node/.n8n/logs', { recursive: true });
const log = (r) => fs.appendFileSync('/home/node/.n8n/logs/content-gen.jsonl',
  JSON.stringify({ ts: new Date().toISOString(), ...r }) + '\n');
const run = (role, input, systemExtra) => this.helpers.httpRequest({
  method: 'POST', url: GW + '/run',
  body: { role: role, input: input, ...(systemExtra ? { system_extra: systemExtra } : {}) },
  json: true, timeout: 300000
});

// brief-gate telegram notify - same env/state contract as sp-tg-moderation
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const notify = async (text) => {
  try {
    const st = JSON.parse(fs.readFileSync('/home/node/.n8n/state/tg.json', 'utf8'));
    if (!st.chat_id || !ENV('TELEGRAM_BOT_TOKEN')) return;
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + ENV('TELEGRAM_BOT_TOKEN') + '/sendMessage',
      body: { chat_id: st.chat_id, text: text }, json: true, timeout: 15000
    });
  } catch (e) { log({ stage: 'notify', error: String(e) }); }
};

// anti-slop filter: banned phrases (EN + RU), emoji bullets, thin entity usage
const BANNED = [/\bdelve\b/i, /\bleverage\b/i, /\btapestry\b/i, /game-?changer/i,
  /excited to announce/i, /fast-?paced world/i, /\bunlock\b/i, /\belevate\b/i,
  /\bsynergy\b/i, /\bdelve into\b/i,
  /в современном мире/i, /давайте разберём/i, /давайте разберем/i,
  /погрузимся/i, /не секрет,? что/i, /важно отметить/i,
  /(^|[^а-яёa-z])важно([^а-яёa-z]|$)/i,
  /(^|[^а-яёa-z])критично([^а-яёa-z]|$)/i,
  /(^|[^а-яёa-z])мелочь([^а-яёa-z]|$)/i];
const EMOJI_BULLET = /^\s*[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u;
const humanize = (t) => String(t)
  .replace(/[\u2014\u2013]/g, '-')
  .replace(/[\u200B-\u200F\uFEFF\u2060]/g, '')
  .replace(/[\u201C\u201D\u201E]/g, '"')
  .replace(/[\u2018\u2019\u201A]/g, "'")
  .replace(/\u2026/g, '...')
  .replace(/\u00A0/g, ' ')
  .replace(/[ \t]+\n/g, '\n')
  .trim();

const MAP = {
  linkedin: ['writer-linkedin'],
  facebook: ['writer-fb'], fb: ['writer-fb'],
  vk: ['writer-vk'],
  all: ['writer-linkedin', 'writer-fb', 'writer-vk']
};

const results = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const platform = String(b.platform || 'all').toLowerCase();
  const topic = b.topic || '';
  const rawContext = String(b.context || '');
  const context = [
    'Topic: ' + topic,
    b.mode === 'rewrite' ? 'Rewrite request. Editor feedback: ' + (b.feedback || '') : '',
    'Raw context:', rawContext
  ].filter(Boolean).join('\n');

  // Brief gate (source > brief > draft): write only from supplied material.
  // Missing/thin context (<200 chars) or context without fact-like
  // tokens (>=2 tokens containing a digit) = refuse, no LLM calls.
  const factTokens = rawContext.match(/\S*\d\S*/g) || [];
  if (rawContext.trim().length < 200 || factTokens.length < 2) {
    const why = rawContext.trim().length < 200 ? 'short-context' : 'no-facts';
    log({ stage: 'brief-gate', reason: why, topic: topic });
    await notify('no material in brief' + (topic ? ' (' + topic + ')' : '') +
      ' - generation skipped [' + why + ']');
    results.push({ platform: platform, ok: false, stage: 'brief-gate',
      error: 'no material in brief (' + why + ')' });
    continue;
  }

  // brief meta: explicit payload fields win; else read from serialized
  // brief JSON inside context (links[]/scope/accents[] per brief schema)
  let briefMeta = {};
  try {
    const c = JSON.parse(rawContext);
    if (c && typeof c === 'object' && !Array.isArray(c)) briefMeta = c;
  } catch (e) { /* context is raw text, not a serialized brief */ }
  const scope = String(b.scope || briefMeta.scope || '');
  const accents = Array.isArray(b.accents) ? b.accents.map(String)
    : (Array.isArray(briefMeta.accents) ? briefMeta.accents.map(String) : []);
  const links = Array.isArray(b.links) ? b.links
    : (Array.isArray(briefMeta.links) ? briefMeta.links : []);

  // session posts get GENERATED charts instead of archive photos:
  // viz_data[] datasets from the brief are drawn by the host renderer.
  const vizData = Array.isArray(b.viz_data) ? b.viz_data
    : (Array.isArray(briefMeta.viz_data) ? briefMeta.viz_data : []);
  const srcType = String(b.source_type || briefMeta.source_type || '');
  const sessionViz = srcType === 'session' || vizData.length > 0;
  // generated-image path: explicit payload flag gen_image, or a
  // non-retro non-session source_type (hype/hot-topic/news). Session
  // posts keep generated charts; retro/archive and untyped posts keep
  // the archive-photo media-selector path.
  const genImage = b.gen_image === true || b.gen_image === 'true'
    || briefMeta.gen_image === true;
  const genImagePath = !sessionViz && (genImage ||
    (srcType !== '' && srcType !== 'retro' && srcType !== 'archive'));
  // one draft id per produced draft so viz PNGs (named <draft_id>_*.png)
  // map 1:1 to moderation drafts; multi-platform runs get a role suffix
  const draftIdBase = b.draft_id ||
    ('d' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6));

  // Pass 1 - fact extraction (Gemini Flash via llm-gateway)
  let facts = {};
  try {
    const r = await run('extract-facts', context);
    facts = r.json || JSON.parse(r.text);
  } catch (e) {
    log({ stage: 'extract', error: String(e) });
    results.push({ platform: platform, ok: false, stage: 'extract', error: String(e).slice(0, 300) });
    continue;
  }

  // Pass 2 - platform writers (Gemini via llm-gateway, per-manifest model fallback chain)
  const roleList = MAP[platform] || MAP.all;
  for (const role of roleList) {
    const itemDraftId = roleList.length > 1
      ? draftIdBase + '-' + role.replace('writer-', '') : draftIdBase;
    const brief = JSON.stringify({
      topic: topic, mode: b.mode || 'new', feedback: b.feedback || null,
      scope: scope || null, accents: accents, links: links, facts: facts
    });
    let text = '', parsed = null, warnings = [];
    let mediaSel = { selected: [], caption_note: '' };
    try {
      let r = await run(role, brief);
      parsed = r.json || JSON.parse(r.text);
      text = parsed.text || '';
      // anti-slop check, then one rewrite pass with violation feedback
      let violations = BANNED.filter(rx => rx.test(text)).map(rx => rx.source);
      if (text.split('\n').some(l => EMOJI_BULLET.test(l))) violations.push('emoji-bullet');
      const ents = [...(facts.stack || []), ...(facts.metrics || [])].map(String);
      if (ents.filter(e => e && text.toLowerCase().includes(e.toLowerCase())).length < 2) {
        violations.push('thin-entities');
      }
      if (violations.length) {
        r = await run(role, brief,
          'Rewrite fixing violations: ' + violations.join(', ') + '. Keep the same JSON output format.');
        parsed = r.json || JSON.parse(r.text);
        text = parsed.text || '';
      }
      // Pass 3 - deterministic humanizer
      text = humanize(text);
      if (parsed) parsed.text = text;

      // Pass 4 - verifier: critic checks draft against brief facts/scope.
      // Invented claims -> one rewrite attempt -> final warnings still go
      // to moderation with the draft.
      const verifyInput = (t) => JSON.stringify({
        topic: topic, platform: role.replace('writer-', ''),
        scope: scope || null, accents: accents, links: links,
        facts: facts, draft: t
      });
      const issueText = (i) => ((i.type || 'issue') + ': ' + (i.detail || '')).slice(0, 200);
      try {
        let vr = await run('critic', verifyInput(text));
        let ver = vr.json || JSON.parse(vr.text);
        let issues = Array.isArray(ver.issues) ? ver.issues : [];
        const blocking = issues.filter(i => i.type === 'fact' || i.type === 'scope');
        if (ver.verdict === 'reject' || blocking.length) {
          const fixList = issues.map(issueText).join('; ') || ver.one_line || 'verdict reject';
          const r2 = await run(role, brief,
            'Verifier flagged invented or out-of-scope content: ' + fixList +
            '. Rewrite using ONLY the supplied facts and links, stay inside scope. ' +
            'Keep the same JSON output format.');
          const p2 = r2.json || JSON.parse(r2.text);
          if (p2 && p2.text) { parsed = p2; text = humanize(p2.text); parsed.text = text; }
          const vr2 = await run('critic', verifyInput(text));
          ver = vr2.json || JSON.parse(vr2.text);
          issues = Array.isArray(ver.issues) ? ver.issues : [];
          warnings = issues.map(issueText);
          if (ver.verdict === 'reject' && !warnings.length) {
            warnings.push('verifier verdict: reject - ' + (ver.one_line || 'no detail'));
          }
          log({ stage: 'verify', role: role, verdict: ver.verdict, rewritten: true,
            warnings: warnings.length });
        } else {
          // non-blocking issues (voice/format/slop) still reach the moderator
          warnings = issues.map(issueText);
          log({ stage: 'verify', role: role, verdict: ver.verdict, rewritten: false,
            warnings: warnings.length });
        }
      } catch (e) {
        log({ stage: 'verify', role: role, error: String(e).slice(0, 300) });
        warnings = ['verifier unavailable - draft not fact-checked'];
      }

      // Pass 5 - media. Three paths:
      //  a) session posts (source_type=session or viz_data present):
      //     GENERATED charts. viz-spec picks 0-2 specs referencing
      //     viz_data[] ids, the host render daemon draws PNGs into
      //     materials/viz/ and returns paths for sendPhoto. Render
      //     failures degrade to text-only - the draft still moderates.
      //  b) generated-image posts (gen_image:true in the payload, or a
      //     non-retro non-session source_type like hype/hot-topic):
      //     the image-gen role emits 1-2 text-to-image prompts
      //     tailored to the draft accents, llm-gateway /image renders
      //     each via a Gemini image model into materials/img/ and
      //     returns paths for sendPhoto. Failures degrade to
      //     text-only.
      //  c) other posts (retro/archive, untyped): media-selector
      //     picks 0-2 files from media[] candidates as before.
      if (sessionViz) {
        if (vizData.length) {
          try {
            const vsr = await run('viz-spec', JSON.stringify({
              text: text, platform: role.replace('writer-', ''),
              accents: accents, viz_data: vizData
            }));
            const vs = vsr.json || JSON.parse(vsr.text);
            const knownIds = new Set(vizData.map((d) => d && d.id));
            const specs = (Array.isArray(vs.charts) ? vs.charts : [])
              .filter((s) => s && knownIds.has(s.viz_id)).slice(0, 2);
            if (specs.length) {
              const rr = await this.helpers.httpRequest({
                method: 'POST', url: VIZ, json: true, timeout: 120000,
                body: { draft_id: itemDraftId, specs: specs, viz_data: vizData }
              });
              mediaSel.selected = (rr && Array.isArray(rr.paths) ? rr.paths : [])
                .map(String).slice(0, 2);
              mediaSel.caption_note = 'generated charts: ' +
                specs.map((s) => s.type + '/' + s.viz_id).join(', ') +
                (vs.note ? ' - ' + String(vs.note).slice(0, 150) : '');
            }
            log({ stage: 'viz', role: role, draft_id: itemDraftId,
              datasets: vizData.length, specs: specs.length,
              rendered: mediaSel.selected });
          } catch (e) {
            let ed; try { ed = JSON.stringify(e); } catch (_) { ed = String(e); }
            log({ stage: 'viz', role: role, error: String(ed).slice(0, 400) });
          }
        }
      } else if (genImagePath) {
      // image generation: image-gen emits 1-2 image prompts; each is
      // rendered by the gateway POST /image into materials/img/.
      try {
        const igr = await run('image-gen', JSON.stringify({
          text: text, platform: role.replace('writer-', ''),
          accents: accents, topic: topic
        }));
        const igs = igr.json || JSON.parse(igr.text);
        const imgSpecs = (Array.isArray(igs.images) ? igs.images : [])
          .map((s) => (typeof s === 'string' ? { prompt: s, caption: '' } : s))
          .filter((s) => s && s.prompt).slice(0, 2);
        const imgPaths = [];
        for (let k = 0; k < imgSpecs.length; k++) {
          try {
            const ir = await this.helpers.httpRequest({
              method: 'POST', url: GW + '/image', json: true, timeout: 180000,
              body: { prompt: String(imgSpecs[k].prompt), name: itemDraftId + '_' + k }
            });
            if (ir && ir.path) imgPaths.push(String(ir.path));
          } catch (e2) {
            log({ stage: 'image', role: role, draft_id: itemDraftId,
              step: 'render', error: String(e2).slice(0, 300) });
          }
        }
        mediaSel.selected = imgPaths;
        mediaSel.caption_note = 'generated image(s): ' +
          imgSpecs.map((s) => String(s.caption || '')).filter(Boolean).join('; ') +
          (igs.note ? ' - ' + String(igs.note).slice(0, 120) : '');
        log({ stage: 'image', role: role, draft_id: itemDraftId,
          prompts: imgSpecs.length, rendered: mediaSel.selected });
      } catch (e) {
        log({ stage: 'image', role: role, error: String(e).slice(0, 300) });
      }
      } else {
      // media selection: candidates come from payload media[] or
      // a serialized brief's media[] (strings or {path, desc}). The
      // selector matches them against the draft's accents and picks 0-2;
      // an empty selection is valid - the post then goes text-only.
      const mediaCands = (Array.isArray(b.media) ? b.media
        : (Array.isArray(briefMeta.media) ? briefMeta.media : []))
        .map((m) => (typeof m === 'string'
          ? { path: m, desc: '' }
          : { path: String((m && m.path) || ''),
              desc: String((m && (m.desc || m.description)) || '') }))
        .filter((m) => m.path);
      if (mediaCands.length) {
        try {
          const mr = await run('media-selector', JSON.stringify({
            text: text, platform: role.replace('writer-', ''),
            accents: accents, candidates: mediaCands
          }));
          const mp = mr.json || JSON.parse(mr.text);
          const known = new Set(mediaCands.map((c) => c.path));
          mediaSel.selected = (Array.isArray(mp.selected) ? mp.selected : [])
            .map(String).filter((p) => known.has(p)).slice(0, 2);
          mediaSel.caption_note = String(mp.caption_note || '');
          log({ stage: 'media', role: role, candidates: mediaCands.length,
            selected: mediaSel.selected, note: mediaSel.caption_note });
        } catch (e) {
          log({ stage: 'media', role: role, error: String(e).slice(0, 300) });
        }
      }
      }
    } catch (e) {
      log({ stage: 'write', role: role, error: String(e) });
      results.push({ platform: role, ok: false, stage: 'write', error: String(e).slice(0, 300) });
      continue;
    }

    // to Telegram moderation
    try {
      const mod = await this.helpers.httpRequest({
        method: 'POST', url: MOD, json: true,
        body: {
          draft_id: itemDraftId,
          platform: (parsed && parsed.platform) || role.replace('writer-', ''),
          topic: topic, text: text, image: b.image || '', source: 'content-gen',
          scope: scope || undefined,
          warnings: warnings.length ? warnings : undefined,
          media: mediaSel.selected.length ? mediaSel.selected : undefined,
          caption_note: mediaSel.caption_note || undefined
        }
      });
      results.push({ platform: role, ok: true, draft_id: mod.draft_id, warnings: warnings.length });
      log({ stage: 'moderate', role: role, draft_id: mod.draft_id, warnings: warnings.length });
    } catch (e) {
      log({ stage: 'moderate', role: role, error: String(e) });
      results.push({ platform: role, ok: false, stage: 'moderate', error: String(e).slice(0, 300) });
    }
  }
}
return [{ json: { ok: true, results: results } }];
